// GENERATED by scripts/sync-race-shared.mjs from src/race — do not edit here.
/**
 * Deterministic race simulation.
 *
 * - All randomness comes from a seeded PRNG and is pre-rolled per racer in the
 *   constructor, so two clients with the same seed + racers see the same race.
 * - Physics advance with a fixed time step (accumulator), so frame rate never
 *   changes the outcome. Renderers interpolate with `renderDistance()`.
 * - Units: metres and seconds.
 */
import seedrandom from 'seedrandom';
import type { BodyColor } from './sprites.ts';

export type RacerPhase = 'idle' | 'running' | 'curling' | 'rolling' | 'finished';

export interface RacerStats {
  /** 0–100 */
  speed: number;
  /** 0–100 (Burst Power) */
  burst: number;
  /** 0–100 */
  endurance: number;
}

export interface RacerInput {
  id: string;
  name: string;
  body: BodyColor;
  /** URL of the open-pose artwork (the NFT image). null → ball only */
  avatarUrl: string | null;
  isPlayer: boolean;
  stats: RacerStats;
  /** `Weather Adaptation` trait; matching the track terrain gives a bonus */
  terrainAffinity?: string | null;
}

interface FormSegment { t: number; value: number }
interface Event { t: number; duration: number; mult: number }

export interface RacerSim extends RacerInput {
  distance: number;
  prevDistance: number;
  speed: number;
  maxSpeed: number;
  accel: number;
  phase: RacerPhase;
  /** seconds spent in current phase */
  phaseTime: number;
  finishTime: number | null;
  position: number;
  /** Fixed saddle number 1..N (lane order); what the caller says and the HUD shows. */
  number: number;
  /** current multiplier from form noise + events (for FX intensity) */
  formMult: number;
  /** >0 while a burst event is active (renderers can show speed lines) */
  burstLeft: number;
  /** >0 while stumbling */
  stumbleLeft: number;
  _form: FormSegment[];
  _events: Event[];
  /** final-stretch speed retention, 0.9–1.0 */
  _enduranceFactor: number;
  /** seconds of open-pose sprinting before curling */
  _curlAt: number;
}

export interface SimulationOptions {
  /** total race length in metres */
  distance: number;
  terrain: string;
  /** fixed physics step, seconds */
  fixedDt?: number;
}

export const DEFAULT_RACE_DISTANCE = 400;
const FIXED_DT = 1 / 60;
/** fraction of max speed a running pangolin must reach before it may curl into a ball */
const ROLL_THRESHOLD = 0.55;
const CURL_DURATION = 0.45;
/** minimum seconds spent sprinting in the open pose before curling (high Burst → sooner) */
const MIN_RUN_TIME = 2.4;
const RUN_TIME_SPREAD = 1.2;

/** Maps a 0–100 trait to an "effective" 50–80 band so weak NFTs still compete. */
export function effectiveStat(v: number): number {
  const c = Math.max(0, Math.min(100, Number.isFinite(v) ? v : 50));
  return 50 + c * 0.3;
}

export class RaceSimulation {
  readonly racers: RacerSim[];
  readonly totalDistance: number;
  readonly terrain: string;
  readonly fixedDt: number;
  /** simulated race clock; negative while idle */
  time = 0;
  started = false;
  finished = false;
  private accumulator = 0;
  private finishedCount = 0;

  constructor(seed: string, inputs: RacerInput[], opts: SimulationOptions) {
    this.totalDistance = opts.distance;
    this.terrain = opts.terrain;
    this.fixedDt = opts.fixedDt ?? FIXED_DT;
    const rng = seedrandom(seed);

    this.racers = inputs.map((input, i) => {
      const sp = effectiveStat(input.stats.speed);
      const bu = effectiveStat(input.stats.burst);
      const en = effectiveStat(input.stats.endurance);
      // Matching Weather Adaptation: a real but not overwhelming edge (~0.5 s over 400 m)
      const terrainBonus = input.terrainAffinity && input.terrainAffinity.toLowerCase() === opts.terrain.toLowerCase() ? 1.025 : 1;

      // max speed ≈15.9–19.1 m/s, acceleration 6–9 m/s². The stat spread is deliberately
      // narrower than the luck spread below so a mid-range NFT still has a shot at the podium.
      const maxSpeed = (17.5 + ((sp - 50) / 30) * 1.6) * terrainBonus;
      const accel = 6 + ((bu - 50) / 30) * 3;

      // Pre-roll form noise: a new target every 1.4–2.6 s, smooth multiplier in [0.90, 1.10]
      const form: FormSegment[] = [];
      let t = 0;
      while (t < 180) {
        form.push({ t, value: 0.9 + rng() * 0.2 });
        t += 1.4 + rng() * 1.2;
      }

      // Events: 1–2 bursts, 0–1 stumbles depending on endurance
      const events: Event[] = [];
      const burstCount = 1 + (rng() < 0.5 ? 1 : 0);
      for (let b = 0; b < burstCount; b++) {
        events.push({ t: 3 + rng() * 16, duration: 1.2 + rng() * 0.8, mult: 1.18 + rng() * 0.1 });
      }
      const stumbleChance = 0.35 - ((en - 50) / 30) * 0.3; // high endurance → fewer stumbles
      if (rng() < stumbleChance) {
        events.push({ t: 4 + rng() * 14, duration: 0.7 + rng() * 0.4, mult: 0.7 });
      }

      return {
        ...input,
        distance: 0,
        prevDistance: 0,
        speed: 0,
        maxSpeed,
        accel,
        phase: 'idle',
        phaseTime: 0,
        finishTime: null,
        position: i + 1,
        number: i + 1,
        formMult: 1,
        burstLeft: 0,
        stumbleLeft: 0,
        _form: form,
        _events: events,
        _enduranceFactor: 0.9 + ((en - 50) / 30) * 0.1,
        _curlAt: MIN_RUN_TIME + (1 - (bu - 50) / 30) * RUN_TIME_SPREAD * 0.5 + rng() * 0.5,
      };
    });
  }

  /** Starts the clock; racers switch from idle to running. */
  start() {
    if (this.started) return;
    this.started = true;
    this.time = 0;
    for (const r of this.racers) this.setPhase(r, 'running');
  }

  /** Advance by a wall-clock delta (seconds). Returns interpolation alpha for rendering. */
  step(dt: number): number {
    if (!this.started || this.finished) return 1;
    this.accumulator += Math.min(dt, 0.25);
    while (this.accumulator >= this.fixedDt) {
      this.tick(this.fixedDt);
      this.accumulator -= this.fixedDt;
      if (this.finished) break;
    }
    return this.accumulator / this.fixedDt;
  }

  /** Distance to draw for racer, interpolated between physics steps. */
  renderDistance(r: RacerSim, alpha: number): number {
    return r.prevDistance + (r.distance - r.prevDistance) * Math.max(0, Math.min(1, alpha));
  }

  /** Racers sorted by current standing (finished first by time, then by distance). */
  standings(): RacerSim[] {
    return [...this.racers].sort((a, b) => {
      if (a.finishTime !== null && b.finishTime !== null) return a.finishTime - b.finishTime;
      if (a.finishTime !== null) return -1;
      if (b.finishTime !== null) return 1;
      return b.distance - a.distance;
    });
  }

  private setPhase(r: RacerSim, phase: RacerPhase) {
    r.phase = phase;
    r.phaseTime = 0;
  }

  private formAt(r: RacerSim, t: number): number {
    const segs = r._form;
    let i = 0;
    while (i + 1 < segs.length && segs[i + 1].t <= t) i++;
    const a = segs[i];
    const b = segs[Math.min(i + 1, segs.length - 1)];
    const span = Math.max(0.001, b.t - a.t);
    const k = Math.max(0, Math.min(1, (t - a.t) / span));
    const s = k * k * (3 - 2 * k); // smoothstep
    return a.value + (b.value - a.value) * s;
  }

  private tick(dt: number) {
    this.time += dt;
    for (const r of this.racers) {
      r.prevDistance = r.distance;
      r.phaseTime += dt;
      if (r.phase === 'finished') continue;

      // Event multipliers
      let eventMult = 1;
      r.burstLeft = 0;
      r.stumbleLeft = 0;
      for (const e of r._events) {
        if (this.time >= e.t && this.time < e.t + e.duration) {
          eventMult *= e.mult;
          if (e.mult > 1) r.burstLeft = e.t + e.duration - this.time;
          else r.stumbleLeft = e.t + e.duration - this.time;
        }
      }

      // Endurance: fade in the final 40% of the race for low-endurance racers
      const progress = r.distance / this.totalDistance;
      const fatigue = progress > 0.6
        ? 1 - (1 - r._enduranceFactor) * ((progress - 0.6) / 0.4)
        : 1;

      r.formMult = this.formAt(r, this.time) * eventMult * fatigue;
      const target = r.maxSpeed * r.formMult;

      // Running pangolins are slower than rolling ones; curl once fast enough
      const rollCap = r.phase === 'running' || r.phase === 'curling' ? r.maxSpeed * 0.7 : Infinity;
      const effectiveTarget = Math.min(target, rollCap);

      // Exponential approach – frame-rate independent by construction (fixed dt anyway)
      const rate = r.speed < effectiveTarget ? r.accel / Math.max(1, r.maxSpeed) * 2.2 : 1.6;
      r.speed += (effectiveTarget - r.speed) * (1 - Math.exp(-rate * dt));

      r.distance += r.speed * dt;

      if (r.phase === 'running' && r.phaseTime >= r._curlAt && r.speed >= r.maxSpeed * ROLL_THRESHOLD) {
        this.setPhase(r, 'curling');
      } else if (r.phase === 'curling' && r.phaseTime >= CURL_DURATION) {
        this.setPhase(r, 'rolling');
      }

      if (r.distance >= this.totalDistance) {
        const overshoot = r.distance - this.totalDistance;
        r.finishTime = this.time - (r.speed > 0 ? overshoot / r.speed : 0);
        r.distance = this.totalDistance;
        this.setPhase(r, 'finished');
        this.finishedCount++;
      }
    }

    const sorted = this.standings();
    sorted.forEach((r, i) => { r.position = i + 1; });
    if (this.finishedCount >= this.racers.length) this.finished = true;
  }
}

/** Deterministically generates bot stats and identity from a seed. */
export function generateBots(seed: string, count: number, usedNames: Set<string> = new Set()): { tokenId: number; stats: RacerStats }[] {
  const rng = seedrandom(`${seed}:bots`);
  const bots: { tokenId: number; stats: RacerStats }[] = [];
  const taken = new Set<number>();
  while (bots.length < count) {
    const tokenId = 1 + Math.floor(rng() * 1000);
    if (taken.has(tokenId) || usedNames.has(String(tokenId))) continue;
    taken.add(tokenId);
    bots.push({
      tokenId,
      stats: {
        speed: 30 + Math.floor(rng() * 45),
        burst: 30 + Math.floor(rng() * 45),
        endurance: 30 + Math.floor(rng() * 45),
      },
    });
  }
  return bots;
}
